$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json") -or -not (Test-Path "database\migrations")) {
  throw "Execute este script na pasta raiz do SaborFlow."
}

Write-Host "=== ETAPA 13.12 - TRILHA DE AUDITORIA ==="

Write-Host "Aplicando: database/migrations/034_security_audit_trail.sql"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "database\migrations\034_security_audit_trail.sql"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Aplicando: lib/security/audit-log.ts"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "lib\security\audit-log.ts"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Aplicando: app/api/admin/audit/route.ts"
$data = [Convert]::FromBase64String("")
$target = Join-Path (Get-Location) "app\api\admin\audit\route.ts"
$dir = Split-Path $target -Parent
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes($target, $data)

Write-Host "Verificando diff..."
git diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check encontrou problema." }

Write-Host "Executando typecheck..."
npm.cmd run typecheck
$typeExit = $LASTEXITCODE
if ($typeExit -ne 0) {
  git restore -- next-env.d.ts 2>$null
  throw "TYPECHECK FALHOU. Envie apenas o erro final."
}

Write-Host "Executando build..."
npm.cmd run build
$buildExit = $LASTEXITCODE
git restore -- next-env.d.ts 2>$null
if ($buildExit -ne 0) { throw "BUILD FALHOU. Envie apenas o erro final." }

Write-Host ""
Write-Host "=============================================="
Write-Host "ETAPA 13.12 PREPARADA - BUILD APROVADO"
Write-Host "=============================================="
Write-Host "- migration 034 criada"
Write-Host "- sf_audit_log estendida com categoria, origem e hashes tecnicos"
Write-Host "- login, senha, 2FA, passkeys e sessoes serao auditados por trigger"
Write-Host "- metadados sensiveis sao ocultados na leitura"
Write-Host "- API /api/admin/audit criada com sessao, permissao e RLS"
Write-Host "- audit log fica append-only para o runtime role"
Write-Host "- Superadmin continua usando sf_platform_admin_actions existente"
Write-Host "- A MIGRATION AINDA NAO FOI APLICADA NO BANCO"
Write-Host "- ainda nao foi feito commit nem deploy"
